async function api(path, options={}) {
  const token = localStorage.getItem('monata-token');
  const request = (accessToken) => { const headers = { ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}), ...options.headers }; return fetch(`${API}${path}`, { ...options, headers }); };
  let res = await request(token);
  if(res.status===401&&token&&localStorage.getItem('monata-refresh')&&!['/auth/login','/auth/register','/auth/refresh','/auth/logout'].includes(path)) {
    try {
      if(!refreshInFlight) refreshInFlight=(async()=>{const refreshToken=localStorage.getItem('monata-refresh');const refreshResponse=await fetch(`${API}/auth/refresh`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refreshToken})});const refreshPayload=await refreshResponse.json().catch(()=>({error:'Session refresh failed'}));if(!refreshResponse.ok||refreshPayload.success===false)throw new Error(refreshPayload.error||'Session expired');const refreshed=refreshPayload.data??refreshPayload;const tokens=refreshed.tokens||refreshed;if(!tokens.accessToken)throw new Error('Session refresh failed');localStorage.setItem('monata-token',tokens.accessToken);if(tokens.refreshToken)localStorage.setItem('monata-refresh',tokens.refreshToken);return tokens.accessToken})().finally(()=>{refreshInFlight=null});
      res=await request(await refreshInFlight);
    } catch { localStorage.removeItem('monata-token');localStorage.removeItem('monata-refresh');throw new Error('Your session expired. Please sign in again.'); }
  }
  const payload = await res.json().catch(()=>({error:'Unexpected response from the server'}));
  if (!res.ok || payload.success === false) throw new Error(payload.error || 'Something went wrong. Please try again.');
  return payload.data;
}

